def sales_page(slug, data):
    url = abs_url(f"solutions/{slug}")
    schema = schema_base(url, data["title"], data["description"])
    schema["@graph"].append({"@type": "Service", "name": data["service"], "provider": {"@id": abs_url() + "#person"}, "areaServed": {"@type": "Country", "name": "Kazakhstan"}, "url": url, "offers": {"@type": "Offer", "priceCurrency": "KZT", "description": data["price"]}})
    schema["@graph"].append({"@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": q, "acceptedAnswer": {"@type": "Answer", "text": a}} for q, a in data["faq"]]})
    fit = "".join(f"<li>{escape(item)}</li>" for item in data["fit"])
    items = "".join(f'<article class="seo-card"><span class="number">0{i}</span><h3>{escape(item)}</h3></article>' for i, item in enumerate(data["items"], 1))
    faq = "".join(f"<details><summary>{escape(q)}</summary><p>{escape(a)}</p></details>" for q, a in data["faq"])
    body = f'''<p class="breadcrumbs"><a href="../../">Главная</a> / <a href="../">Решения</a> / {escape(data['service'])}</p><section class="seo-hero sales-hero"><p class="seo-kicker">Решение под конкретную задачу</p><h1>{escape(data['h1'])}</h1><p class="seo-lead">{escape(data['lead'])}</p><div class="sales-estimate"><span><small>Бюджет</small><strong>{escape(data['price'])}</strong></span><span><small>Срок</small><strong>{escape(data['term'])}</strong></span></div><div class="seo-actions"><a class="seo-button primary" href="../../#selector" data-analytics="selector_started" data-location="sales_page" data-offer="{escape(slug, quote=True)}">Получить план и оценку</a><a class="seo-button" href="{data['case']}">{escape(data['case_label'])}</a></div></section><section class="seo-section"><h2>Когда это решение уместно</h2><ul class="seo-list">{fit}</ul></section><section class="seo-section"><h2>Что входит в первую версию</h2><div class="seo-grid sales-scope">{items}</div></section><aside class="case-disclosure"><strong>Честные границы</strong><p>{escape(data['limits'])}</p></aside><section class="seo-section"><h2>Условия работы</h2><div class="assurance-strip"><article><strong>30 / 40 / 30</strong><span>этапная оплата</span></article><article><strong>Демо</strong><span>рабочая версия по этапам</span></article><article><strong>Исходники</strong><span>код и доступы передаются</span></article><article><strong>Без ТЗ</strong><span>достаточно описать задачу</span></article></div></section><section class="seo-section seo-faq"><h2>Частые вопросы</h2>{faq}</section><section class="seo-section"><h2>Начните с короткого описания.</h2><p>Напишите, что происходит сейчас, кто пользуется процессом и какое действие должно стать проще. Этого достаточно для первого плана.</p><div class="seo-actions"><a class="seo-button primary" href="{CONFIG['instagram']}" rel="noopener" data-analytics="generate_lead" data-location="sales_page_bottom" data-offer="{escape(slug, quote=True)}">Отправить задачу в Instagram</a><a class="seo-button" href="../../pricing/">Все пакеты и цены</a></div></section>'''
    return document(data["title"], data["description"], f"{data['service']}, заказать разработку, Казахстан, Алматы, Астана", url, 2, schema, body)


